+
+Then('the captured reference has class {string}', function (className) {
+  assert.ok(this.capturedReference.classList.contains(className));
+});
+
+Then('the captured reference does not have class {string}', function (className) {
+  assert.ok(!this.capturedReference.classList.contains(className));
+});
+
+Then('the toggle checkbox inside the captured reference is checked', function () {
+  const toggle = this.capturedReference.querySelector('.toggle');
+  assert.ok(toggle.checked);
+});
+
+Then('the toggle checkbox inside the captured reference is not checked', function () {
+  const toggle = this.capturedReference.querySelector('.toggle');
+  assert.ok(!toggle.checked);
+});
+
+Then('each captured reference is still attached to the DOM', function () {
+  for (const ref of this.capturedReferences) {
+    assert.ok(ref.isConnected, 'a captured reference was detached from the DOM');
+  }
+});
+
+Then('each captured reference has class {string}', function (className) {
+  for (const ref of this.capturedReferences) {
+    assert.ok(ref.classList.contains(className));
+  }
+});
+
+Then('the captured references for remaining items are still attached to the DOM', function () {
+  // Remaining items are not completed — they survive clear-completed
+  for (const ref of this.capturedReferences) {
+    if (!ref.classList.contains('completed')) {
+      assert.ok(ref.isConnected, 'a remaining reference was detached from the DOM');
+    }
+  }
+});
+
+Then('the captured references for completed items are detached from the DOM', function () {
+  for (const ref of this.capturedReferences) {
+    if (ref.classList.contains('completed')) {
+      assert.ok(!ref.isConnected, 'a completed reference was still attached to the DOM');
+    }
+  }
+});
+
